syntax:
// All forms are safe with nullptr:
delete nullptr;              // Safe: no-op
delete[] nullptr;            // Safe: no-op

Widget* w = nullptr;
delete w;                    // Safe: no-op
w = new Widget;
delete w;                    // Calls ~Widget(), operator delete
delete w;                    // UB! (double delete)

// Idempotent delete pattern:
delete ptr;
ptr = nullptr;               // Now safe to delete again
delete ptr;                  // Safe: no-op

// Unnecessary (but harmless) null check:
if (ptr != nullptr) {        // Redundant check
    delete ptr;              // delete already handles nullptr
}

// Modern style (no check needed):
delete ptr;                  // Sufficient - handles nullptr internally
ptr = nullptr;               // Make idempotent

code_example:
#include <iostream>

class Widget {
public:
    Widget(const char* name) : name_(name) {
        std::cout << "Widget(" << name_ << ") constructed\n";
    }
    ~Widget() {
        std::cout << "~Widget(" << name_ << ") destroyed\n";
    }
private:
    const char* name_;
};

// Track deallocation calls
void operator delete(void* ptr) noexcept {
    std::cout << "operator delete(" << ptr << ")\n";
    std::free(ptr);
}

void operator delete[](void* ptr) noexcept {
    std::cout << "operator delete[](" << ptr << ")\n";
    std::free(ptr);
}

void demonstrate_null_safety() {
    std::cout << "=== Null Pointer Delete Safety ===\n\n";

    // 1. Deleting nullptr literal
    std::cout << "1. delete nullptr:\n";
    delete nullptr;  // Safe: no output (no destructor, no operator delete)
    std::cout << "   No-op completed successfully\n\n";

    // 2. Deleting null pointer variable
    std::cout << "2. delete null pointer variable:\n";
    Widget* w1 = nullptr;
    delete w1;  // Safe: no-op
    std::cout << "   No-op completed successfully\n\n";

    // 3. Deleting valid pointer
    std::cout << "3. delete valid pointer:\n";
    Widget* w2 = new Widget("w2");
    delete w2;  // Calls destructor and operator delete
    std::cout << "\n";

    // 4. Idempotent delete pattern
    std::cout << "4. Idempotent delete pattern:\n";
    Widget* w3 = new Widget("w3");
    delete w3;
    w3 = nullptr;  // Critical: makes subsequent deletes safe
    std::cout << "   Deleting again (now nullptr):\n";
    delete w3;  // Safe: no-op because w3 is nullptr
    std::cout << "   No-op completed successfully\n\n";

    // 5. Array delete with nullptr
    std::cout << "5. delete[] nullptr:\n";
    Widget* arr = nullptr;
    delete[] arr;  // Safe: no-op
    std::cout << "   No-op completed successfully\n\n";

    // 6. RAII pattern - safe in destructor
    class ResourceHolder {
    public:
        ResourceHolder(bool allocate) {
            if (allocate) {
                resource_ = new Widget("held");
            }
            // If allocate is false, resource_ is nullptr
        }

        ~ResourceHolder() {
            // Safe even if resource_ is nullptr (never allocated)
            delete resource_;  // No need to check!
        }
    private:
        Widget* resource_ = nullptr;
    };

    std::cout << "6. RAII with conditional allocation:\n";
    std::cout << "   Creating holder WITHOUT allocation:\n";
    {
        ResourceHolder holder(false);  // resource_ stays nullptr
    }  // Destructor deletes nullptr - safe!
    std::cout << "   Destructor safely deleted nullptr\n\n";

    std::cout << "   Creating holder WITH allocation:\n";
    {
        ResourceHolder holder(true);  // resource_ allocated
    }  // Destructor deletes valid pointer
    std::cout << "   Destructor deleted valid pointer\n";
}

void demonstrate_antipatterns() {
    std::cout << "\n=== Anti-patterns (unnecessary checks) ===\n\n";

    Widget* w = nullptr;

    // Anti-pattern: redundant check
    std::cout << "Anti-pattern (redundant check):\n";
    if (w != nullptr) {  // Unnecessary
        delete w;
    }
    std::cout << "Check was redundant - delete handles nullptr\n\n";

    // Better: trust the language
    std::cout << "Better (no check):\n";
    delete w;  // Safe, concise, correct
    std::cout << "Just delete - it's already safe\n";
}

int main() {
    demonstrate_null_safety();
    demonstrate_antipatterns();
    return 0;
}

